/**
 * Turns the template gallery (src/client/engine/gallery.ts) into the Fluent
 * records the app installs: one JSON body per template, and one .now.ts file
 * that declares a template record for each.
 *
 * Runs before `now-sdk build` (see package.json). It loads the gallery
 * straight from TypeScript, which needs Node 22.18 or later; on an older Node
 * it says so and leaves the generated files as they are, so a build still
 * succeeds with the starters as they were last generated.
 *
 * Output is deterministic: running it twice changes nothing.
 */
import { mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const galleryPath = join(root, 'src/client/engine/gallery.ts')
const outDir = join(root, 'src/fluent/templates')
const bodyDir = join(outDir, 'starters')

// Loaded from a copy named .mts: the package is not "type": "module", and
// the gallery imports only types, which Node strips, so the copy stands alone.
let gallery
const scratch = mkdtempSync(join(tmpdir(), 'templater-starters-'))
try {
    const copy = join(scratch, 'gallery.mts')
    writeFileSync(copy, readFileSync(galleryPath, 'utf8'))
    ;({ GALLERY: gallery } = await import(pathToFileURL(copy).href))
} catch (failure) {
    console.warn(
        `[starters] Could not load ${galleryPath} (${failure.message.split('\n')[0]}).\n` +
            '[starters] Node 22.18+ runs TypeScript directly; keeping the starter templates as last generated.'
    )
} finally {
    rmSync(scratch, { recursive: true, force: true })
}
if (!gallery) process.exit(0)

const keys = new Set()
for (const entry of gallery) {
    if (!/^[a-z0-9-]+$/.test(entry.key)) throw new Error(`[starters] "${entry.key}" is not a valid key.`)
    if (keys.has(entry.key)) throw new Error(`[starters] "${entry.key}" is used twice.`)
    keys.add(entry.key)
}

/** Writes a file only when its content changed, so the build does not see churn. */
const write = (path, content) => {
    let current = null
    try {
        current = readFileSync(path, 'utf8')
    } catch {}
    if (current !== content) writeFileSync(path, content)
}

mkdirSync(bodyDir, { recursive: true })

// A body whose template left the gallery goes with it. The record itself is
// not deleted from instances it was installed on — see the README.
for (const file of readdirSync(bodyDir)) {
    if (file.endsWith('.json') && !keys.has(file.slice(0, -'.json'.length))) rmSync(join(bodyDir, file))
}

for (const entry of gallery) write(join(bodyDir, `${entry.key}.json`), `${JSON.stringify(entry.body, null, 2)}\n`)

const literal = value => JSON.stringify(value)

const records = gallery.map(
    entry => `Record({
    $id: Now.ID['starter-${entry.key}'],
    table: 'x_1040823_template_template',
    data: {
        name: ${literal(entry.name)},
        kind: ${literal(entry.kind)},
        table: ${literal(entry.table)},
        description: ${literal(entry.description)},
        active: true,
        query: ${literal(entry.query)},
        order_by: ${literal(entry.orderBy)},
        record_limit: ${entry.limit},
        body: Now.include('./starters/${entry.key}.json'),
    },
})`
)

write(
    join(outDir, 'starters.now.ts'),
    `/*
 * GENERATED by scripts/build-starters.mjs from src/client/engine/gallery.ts.
 * Edit the gallery and run \`npm run starters\` (or \`npm run build\`), not this file.
 *
 * The starter templates the app installs. They are app records: a deploy puts
 * them back as the gallery describes them, so a template meant to be changed
 * on the instance should be duplicated first.
 */
import '@servicenow/sdk/global'
import { Record } from '@servicenow/sdk/core'

${records.join('\n\n')}
`
)

console.log(`[starters] ${gallery.length} starter templates → src/fluent/templates/`)
